INSERT INTO `PAGINA` (`pagina_id`, `protetor_id`, `descricao`, `foto_fundo`, `foto_perfil`, `chave_pix`) VALUES
(4, 4, 'Protetor independente: resgato e cuido de cães até encontrarem um novo lar.', NULL, 'https://i.pravatar.cc/300?img=3', NULL),
(5, 5, 'Cuido de gatos resgatados até a adoção responsável.', NULL, 'assets/uploads/foto_pagina/67fd5ab910d4b6ef37c316d80c2bf622.png', NULL),
(6, 6, 'queremos o bem animal', NULL, 'assets/uploads/foto_pagina/6664ff8c8da68fd17922ef42c87a72b9.png', NULL),
(7, 7, 'Somos uma ONG fictícia de demonstração do CãoNectados, dedicada ao acolhimento de cães e gatos sem raça definida em Foz do Iguaçu. Nosso trabalho reúne resgate, cuidados veterinários, lares temporários e adoção responsável. Cada patinha merece segurança, carinho e uma nova família.', 'assets/uploads/foto_pagina/ebbb07635548d23d581c74eb501d2398.png', 'assets/uploads/foto_pagina/7fc1954e804741b139304c1f8d2bd89e.png', NULL),
(8, 8, 'Somos uma rede de voluntários dedicada ao resgate e ao acolhimento temporário. Preparamos cada animal para encontrar uma família que respeite suas necessidades.', 'assets/uploads/foto_pagina/69548b157f8bc6351fcb21ab4788bfb2.png', 'assets/uploads/foto_pagina/8a308ef53faeb90468ba5f21a329db4e.png', NULL),
(9, 9, 'Oferecemos uma nova chance a animais resgatados por meio de acolhimento temporário e adoção responsável. Cuidamos da recuperação e socialização de cada pet e buscamos famílias comprometidas com carinho, segurança e cuidados durante toda a vida.', 'assets/uploads/foto_pagina/49019c678b5c6487de644bf849cabb1e.png', 'assets/uploads/foto_pagina/226005a868035f4ed67255c2c60c2091.png', NULL),
(10, 10, 'A ONG Abrigo Novo Amanhã acolhe animais resgatados e oferece cuidado, proteção e uma nova oportunidade. Trabalhamos com lares temporários e adoção responsável, buscando famílias comprometidas com o bem-estar de cada animal.', 'assets/uploads/foto_pagina/3153a5a1234a1c92b1c4ec22695344a5.png', 'assets/uploads/foto_pagina/8fbfde9699fa5cfdc2267e4baeff2e1c.png', NULL),
(11, 11, 'Acolho cães, gatos e pequenos animais até encontrarem famílias responsáveis. Ofereço orientação para uma adaptação cuidadosa.', NULL, 'https://i.pravatar.cc/300?img=47', NULL),
(12, 12, 'Sou protetor independente e ofereço acolhimento temporário a animais resgatados. Busco famílias preparadas para os cuidados diários.', NULL, 'https://i.pravatar.cc/300?img=12', NULL),
(13, 13, 'Ofereço lar temporário e apoio à adoção responsável, respeitando a personalidade e as necessidades de cada animal.', NULL, 'https://i.pravatar.cc/300?img=44', NULL),
(14, 14, 'Participo de resgates e acolho animais temporariamente. Procuro famílias comprometidas com carinho, segurança e cuidados veterinários.', NULL, 'https://i.pravatar.cc/300?img=13', NULL),
(15, 15, 'Adotar todos os animais de foz', NULL, 'assets/uploads/foto_pagina/bca9d2da479f634fbb655c90292f81fc.png', NULL),
(16, 16, 'testetestetestetesteteste', NULL, NULL, NULL);
INSERT INTO `ADOTANTE` (`adotante_id`, `usuario_id`, `tipo_moradia`, `foto_perfil`, `descricao`, `tamanho_interno_moradia`, `detalhes`, `petiscos_diarios`, `criado_em`, `deletado_em`) VALUES
