INSERT INTO `ANIMAL` (`animal_id`, `protetor_id`, `raca_id`, `nome`, `dt_nasc`, `sexo`, `porte`, `status`, `descricao`, `vacinado`, `castrado`, `comportamento`, `historico_saude`, `criado_em`, `deletado_em`, `atualizado_em`) VALUES
(1, 6, 2, 'Thor', '2024-07-12', 'macho', 'grande', 'adotado', 'Nasceu bem e tals', 1, 1, 'docil', 'Tá vivo', '2026-10-30 18:29:31', NULL, '2026-11-12 16:45:14'),
(2, 6, 5, 'Flocos', '2026-09-01', 'macho', 'grande', 'disponivel', 'Acabou de nascer e quer uma casa', 1, 0, 'arisco', 'Vacinado', '2026-10-30 18:37:01', NULL, '2026-10-30 19:25:50'),
(3, 6, 1, 'Caramelão', '2011-09-11', 'macho', 'medio', 'adotado', 'Era da rua po', 0, 0, 'docil', 'É viralata, logo é saudável ', '2026-10-30 18:42:59', NULL, '2026-11-06 18:18:45'),
(4, 7, 1, 'Bento — cachorro caramelo', '2023-11-02', 'macho', 'medio', 'disponivel', 'Bento é um vira-lata caramelo que conquista todo mundo com seu olhar curioso e o rabinho animado. Adora passear, brincar de bolinha e descansar perto das pessoas. Procura uma família que ofereça passeios diários e um ambiente seguro. Convive bem com outros cães após apresentação gradual.', 1, 1, 'docil', 'Vacinação e vermifugação em dia. Sem condições crônicas conhecidas.', '2026-11-02 16:59:37', NULL, '2026-11-02 18:29:16'),
(5, 7, 1, 'Cachorrinha preta e branca', '2025-05-02', 'femea', 'pequeno', 'disponivel', 'Pequena no tamanho e enorme na alegria, Ela ama brinquedos e companhia. É uma cachorrinha esperta, curiosa e cheia de energia. Pode viver em apartamento com passeios e atividades diárias. Precisa de adaptação tranquila e supervisão ao conhecer outros animais.', 1, 1, 'ativo', 'acinação e vermifugação em dia.', '2026-11-02 17:01:27', NULL, '2026-11-02 18:29:24'),
(6, 7, 4, 'Gata tricolor', '2026-10-02', 'femea', 'pequeno', 'disponivel', 'Gosta de ambientes tranquilos, esconderijos e lugares altos para descansar. A adoção exige janelas teladas e permanência dentro de casa.', 1, 0, 'docil', 'Vacinação e vermifugação em dia', '2026-11-02 17:02:58', NULL, '2026-11-02 18:29:38'),
(7, 7, 4, 'Fubá', '2024-11-02', 'macho', 'medio', 'disponivel', 'Fubá é um gatinho laranja especialista em cochilar ao sol e acompanhar a rotina da casa. Gosta de carinho, arranhadores e brincadeiras com varinhas. Procura um lar com janelas teladas e sem acesso à rua. A convivência com outros gatos deve começar com adaptação gradual.', 1, 1, 'calmo', 'Vacinação e vermifugação em dia. Não informar resultados de FIV/FeLV sem exame.', '2026-11-02 17:04:22', NULL, '2026-11-02 18:29:04'),
(8, 7, 4, 'Pipoca', '2026-05-20', 'femea', 'pequeno', 'adotado', 'Precisa de uma família paciente para acompanhar seu crescimento, oferecer brincadeiras diárias e manter a casa telada, sem acesso à rua.', 1, 0, 'docil', 'Vacinação adequada à idade. Castração deverá ser orientada e programada com médico-veterinário.', '2026-11-02 17:05:19', NULL, '2026-11-02 18:28:32'),
(9, 8, 1, 'Dengo', '2023-06-05', 'macho', 'pequeno', 'disponivel', 'Dengo é um cão bege, carinhoso e companheiro. Gosta de passeios tranquilos e de descansar perto das pessoas. Procura uma família que ofereça carinho, segurança e uma adaptação cuidadosa.', 1, 1, 'calmo', 'Castrado e vacinado. Manter acompanhamento veterinário de rotina.', '2026-11-02 19:03:39', NULL, '2026-11-02 19:04:39'),
(10, 8, 1, 'Gaia', '2025-02-14', 'femea', 'grande', 'disponivel', 'Gaia é uma cadela preta com o peito branco, cheia de energia e vontade de brincar. Gosta de correr e precisa de exercícios diários, passeios e um ambiente protegido.', 1, 1, 'ativo', 'Castrada e vacinada. Manter acompanhamento veterinário de rotina.', '2026-11-02 19:03:39', NULL, '2026-11-02 19:05:21'),
(11, 8, 4, 'Fumaça', '2024-07-22', 'macho', 'pequeno', 'disponivel', 'Fumaça é um gato cinza, dócil e carinhoso. Gosta de receber carinho, explorar arranhadores e descansar em lugares confortáveis. Precisa de um lar com janelas teladas e sem acesso livre à rua.', 1, 1, 'docil', 'Castrado e vacinado. Manter acompanhamento veterinário de rotina.', '2026-11-02 19:03:39', NULL, '2026-11-02 19:06:06'),
(12, 8, 10, 'Cenourinha', '2025-12-10', 'femea', 'pequeno', 'disponivel', 'Cenourinha é uma coelha marrom-clara e curiosa. Gosta de explorar o ambiente e precisa de espaço protegido, feno disponível e proteção contra fios elétricos. Procura uma família preparada para os cuidados próprios de coelhos.', 0, 0, 'ativo', 'Histórico de vacinação e castração não informado. Necessita de avaliação veterinária específica para a espécie.', '2026-11-02 19:03:39', NULL, '2026-11-02 19:06:46'),
(13, 8, 18, 'Pingo', '2025-05-03', 'macho', 'pequeno', 'disponivel', 'Pingo é um periquito azul e branco, ativo e curioso. Gosta de interação e brinquedos próprios para aves. Precisa de recinto adequado, ambiente protegido contra fugas e enriquecimento ambiental.', 0, 0, 'ativo', 'Histórico sanitário não informado. Necessita de acompanhamento veterinário especializado em aves.', '2026-11-02 19:03:39', NULL, '2026-11-02 19:07:18'),
(16, 9, 1, 'Trovão', '2021-10-01', 'macho', 'grande', 'disponivel', 'Trovão é um cão preto e caramelo, companheiro e tranquilo. Gosta de caminhar e descansar perto das pessoas. Procura uma família que ofereça passeios regulares e um ambiente seguro.', 1, 1, 'calmo', 'Castrado e vacinado. Manter acompanhamento veterinário de rotina.', '2026-11-02 19:12:20', NULL, '2026-11-02 19:13:10'),
(17, 9, 1, 'Pipoca', '2026-01-17', 'femea', 'pequeno', 'disponivel', 'Pipoca é uma cadela branca com manchas pretas, muito brincalhona e curiosa. Está aprendendo a passear na guia e precisa de uma família paciente para continuar sua educação com carinho.', 1, 0, 'ativo', 'Vacinada. Castração não informada; necessita de avaliação veterinária.', '2026-11-02 19:12:20', NULL, '2026-11-02 19:13:57'),
(18, 9, 4, 'Amora', '2024-04-09', 'femea', 'pequeno', 'disponivel', 'Amora é uma gata preta, dócil e carinhosa. Adora descansar perto das pessoas e receber carinho. Precisa de um lar com janelas teladas e sem acesso livre à rua.', 1, 1, 'docil', 'Castrada e vacinada. Manter acompanhamento veterinário de rotina.', '2026-11-02 19:12:20', NULL, '2026-11-02 19:14:32'),
(19, 9, 4, 'Floquinho', '2025-06-11', 'macho', 'pequeno', 'disponivel', 'Floquinho é um gato branco e tranquilo. Prefere uma casa calma, com lugares confortáveis para descansar. Precisa de janelas teladas e apresentação gradual a outros animais.', 0, 1, 'calmo', 'Castrado. Histórico de vacinação não informado; conferir com o veterinário.', '2026-11-02 19:12:20', NULL, '2026-11-02 19:15:16'),
(20, 9, 14, 'Paçoca', '2026-02-06', 'femea', 'pequeno', 'adotado', 'Paçoca é uma porquinha-da-índia tricolor, com pelos em rosetas. Curiosa e sociável, gosta de explorar túneis. Precisa de recinto amplo, alimentação adequada e companhia compatível.', 0, 0, 'docil', 'Histórico sanitário e de castração não informado. Necessita de acompanhamento veterinário específico para a espécie.', '2026-11-02 19:12:20', NULL, '2026-11-02 19:16:15'),
(23, 9, 1, 'Pudim', '2026-04-15', 'macho', 'pequeno', 'disponivel', 'Pudim é um cão caramelo com o peito branco, carinhoso e companheiro. Adora brincar com bolinhas, passear e descansar perto das pessoas. Procura uma família que ofereça carinho, passeios diários e um ambiente seguro. A convivência com outros animais deve começar com uma adaptação gradual.', 1, 1, 'ativo', 'Castrado e vacinado. Sem condições de saúde conhecidas. Manter acompanhamento veterinário de rotina.', '2026-11-02 19:18:49', NULL, '2026-11-02 19:18:49'),
(24, 10, 19, 'Mochi', '2026-04-12', 'macho', 'pequeno', 'adotado', 'Mochi é um hamster dourado, curioso e acostumado a explorar túneis. Precisa de recinto individual adequado, substrato para escavar, roda apropriada e esconderijos. Seu período de maior atividade é à noite.', 0, 0, 'calmo', 'Histórico sanitário, vacinação e castração não informados. Necessita de avaliação veterinária específica para a espécie.', '2026-11-02 21:26:06', NULL, '2026-11-02 22:07:28'),
(25, 10, 20, 'Faísca', '2026-03-08', 'femea', 'pequeno', 'desativado', 'Faísca é uma gerbil bege, ágil e curiosa. Gosta de escavar e explorar. Precisa de recinto seguro, substrato profundo e orientação especializada para convivência com outro gerbil compatível.', 0, 0, 'ativo', 'Histórico sanitário, vacinação e castração não informados. Necessita de avaliação veterinária específica para a espécie.', '2026-11-02 21:26:06', '2026-11-02 21:28:25', '2026-11-02 21:28:25'),
(26, 10, 21, 'Veludo', '2024-09-20', 'macho', 'pequeno', 'disponivel', 'Veludo é uma chinchila cinza, observadora e curiosa. Precisa de ambiente fresco, recinto adequado, alimentação própria e banho de pó específico para chinchilas. Procura uma família preparada para os cuidados da espécie.', 0, 0, 'calmo', 'Histórico sanitário, vacinação e castração não informados. Necessita de avaliação veterinária específica para a espécie.', '2026-11-02 21:26:06', NULL, '2026-11-02 21:29:07'),
(27, 10, 22, 'Pixel', '2026-02-15', 'macho', 'pequeno', 'disponivel', 'Pixel é um rato doméstico branco com manchas pretas, sociável e inteligente. Gosta de explorar e interagir. Precisa de recinto enriquecido e companhia compatível de outros ratos domésticos.', 0, 0, 'docil', 'Histórico sanitário, vacinação e castração não informados. Necessita de avaliação veterinária específica para a espécie.', '2026-11-02 21:26:06', NULL, '2026-11-02 21:30:32'),
(28, 10, 23, 'Açafrão', '2025-07-10', 'macho', 'pequeno', 'disponivel', 'Açafrão é um canário doméstico amarelo, ativo e observador. Precisa de recinto espaçoso, poleiros adequados, alimentação própria e ambiente protegido contra fugas.', 0, 0, 'ativo', 'Histórico sanitário, vacinação e castração não informados. Necessita de avaliação veterinária específica para a espécie.', '2026-11-02 21:26:06', NULL, '2026-11-02 21:31:11'),
(31, 4, 10, 'Dourado', '2025-06-11', 'macho', 'pequeno', 'disponivel', 'Bege e curioso. Precisa de feno, espaço seguro e cuidados veterinários próprios da espécie.', 0, 0, 'calmo', 'Histórico sanitário não informado. Avaliação veterinária necessária antes da adoção.', '2026-11-02 22:07:28', NULL, NULL),
(32, 4, 4, 'Safira', '2024-09-16', 'femea', 'pequeno', 'disponivel', 'Cinza e carinhosa. Gosta de observar o movimento e precisa de enriquecimento ambiental.', 0, 0, 'docil', 'Histórico sanitário não informado. Avaliação veterinária necessária antes da adoção.', '2026-11-02 22:07:28', NULL, NULL),
(33, 4, 4, 'Bolinho', '2025-01-12', 'macho', 'pequeno', 'disponivel', 'Branco com manchas marrons. Gosta de descansar perto das pessoas e precisa de janelas teladas.', 0, 0, 'calmo', 'Histórico sanitário não informado. Avaliação veterinária necessária antes da adoção.', '2026-11-02 22:07:28', NULL, NULL),
(34, 4, 1, 'Nala', '2024-07-02', 'femea', 'grande', 'disponivel', 'Preta e brincalhona. Precisa de rotina de exercícios e um espaço protegido.', 0, 0, 'ativo', 'Histórico sanitário não informado. Avaliação veterinária necessária antes da adoção.', '2026-11-02 22:07:28', NULL, NULL),
(35, 4, 1, 'Solano', '2023-03-10', 'macho', 'medio', 'disponivel', 'Caramelo e companheiro. Gosta de passeios e brincadeiras, com adaptação cuidadosa ao novo lar.', 0, 0, 'docil', 'Histórico sanitário não informado. Avaliação veterinária necessária antes da adoção.', '2026-11-02 22:07:28', NULL, NULL),
(36, 5, 26, 'Suspiro', '2024-02-18', 'macho', 'pequeno', 'disponivel', 'Cinza e amarelo, curioso. Precisa de recinto seguro, poleiros apropriados e interação.', 0, 0, 'ativo', 'Histórico sanitário não informado. Avaliação veterinária necessária antes da adoção.', '2026-11-02 22:07:28', NULL, '2026-11-03 02:55:24'),
(37, 5, 4, 'Violeta', '2026-04-07', 'femea', 'pequeno', 'disponivel', 'Tricolor e afetuosa. Gosta de companhia e precisa de adaptação gradual.', 0, 0, 'docil', 'Histórico sanitário não informado. Avaliação veterinária necessária antes da adoção.', '2026-11-02 22:07:28', NULL, '2026-11-03 02:55:59'),
(38, 5, 4, 'Mingau', '2026-10-03', 'macho', 'pequeno', 'disponivel', 'Branco e curioso. Gosta de brinquedos e precisa de um lar seguro e telado.', 0, 0, 'ativo', 'Histórico sanitário não informado. Avaliação veterinária necessária antes da adoção.', '2026-11-02 22:07:28', NULL, '2026-11-03 02:56:47'),
(39, 5, 9, 'Serena', '2026-05-21', 'femea', 'medio', 'disponivel', 'tranquila. Gosta de caminhadas.', 0, 0, 'calmo', 'Histórico sanitário não informado. Avaliação veterinária necessária antes da adoção.', '2026-11-02 22:07:28', NULL, '2026-11-03 02:57:58'),
(40, 5, 1, 'Amendoim', '2023-08-14', 'macho', 'pequeno', 'disponivel', 'Marrom e companheiro. Adora passeios e procura uma família paciente e carinhosa.', 0, 0, 'docil', 'Histórico sanitário não informado. Avaliação veterinária necessária antes da adoção.', '2026-11-02 22:07:28', NULL, '2026-11-03 02:58:28'),
(41, 11, 10, 'Caju', '2025-10-08', 'macho', 'pequeno', 'disponivel', 'Marrom e tranquilo. Precisa de espaço protegido, feno disponível e manejo delicado.', 0, 0, 'calmo', 'Histórico sanitário não informado. Avaliação veterinária necessária antes da adoção.', '2026-11-02 22:07:28', NULL, '2026-11-03 02:36:10'),
(42, 11, 4, 'Nori', '2025-02-16', 'macho', 'pequeno', 'disponivel', 'Preto e branco, curioso e brincalhão. Gosta de arranhadores e precisa de ambiente telado.', 0, 0, 'ativo', 'Histórico sanitário não informado. Avaliação veterinária necessária antes da adoção.', '2026-11-02 22:07:28', NULL, '2026-11-03 02:36:45'),
